(* input: days present in US per year for substantial presence test *)
type presence_days = {
  current_year : int;
  first_preceding_year : int;
  second_preceding_year : int;
}

(* weighted sum of days per multiplier table: current=1, 1st preceding=1/3, 2nd preceding=1/6 *)
let weighted_day_sum (days : presence_days) : float =
  (float_of_int days.current_year *. 1.0) +.
  (float_of_int days.first_preceding_year *. (1.0 /. 3.0)) +.
  (float_of_int days.second_preceding_year *. (1.0 /. 6.0))

(* substantial presence test of 7701(b)(3)(A): 31-day floor in current year AND weighted 3-year sum >= 183 *)
let meets_substantial_presence_test (days : presence_days) : bool =
  days.current_year >= 31 &&
  weighted_day_sum days >= 183.0
